@Composable fun ModernPosAppV2(){
 var page by remember{mutableStateOf("Dashboard")}; var cart by remember{mutableStateOf(emptyList<V2Cart>())}
 val tablet=androidx.compose.ui.platform.LocalConfiguration.current.screenWidthDp>=600
 val pages=listOf("Dashboard","Penjualan","Produk","Persediaan","Pembayaran","Laporan","Pengaturan")
 MaterialTheme(colorScheme=lightColorScheme(primary=V2Brand,background=V2Bg,surface=Color.White,onSurface=V2Ink)){
  Surface(Modifier.fillMaxSize(),color=V2Bg){if(tablet)Row(Modifier.fillMaxSize()){V2Sidebar(page,pages){page=it};Box(Modifier.weight(1f)){V2Content(page,cart,{cart=it})}}else Column(Modifier.fillMaxSize()){Box(Modifier.weight(1f)){V2Content(page,cart,{cart=it})};V2Bottom(page){page=it}}}
 }
}

@Composable private fun V2Sidebar(selected:String,pages:List<String>,onSelect:(String)->Unit){Surface(Modifier.width(244.dp).fillMaxHeight(),color=Color(0xFF171B27)){Column(Modifier.fillMaxSize().padding(14.dp),verticalArrangement=Arrangement.spacedBy(5.dp)){Row(Modifier.padding(8.dp,8.dp,8.dp,18.dp),verticalAlignment=Alignment.CenterVertically){Box(Modifier.size(42.dp).clip(RoundedCornerShape(13.dp)).background(V2Brand),contentAlignment=Alignment.Center){Text("QR",color=Color.White,fontWeight=FontWeight.ExtraBold)};Column(Modifier.padding(start=10.dp)){Text("POS QRIS",color=Color.White,fontSize=18.sp,fontWeight=FontWeight.ExtraBold);Text("Toko Demo • Owner",color=Color(0xFF9CA7BB),fontSize=11.sp)}};pages.forEach{p->val active=p==selected;Surface(Modifier.fillMaxWidth().clip(RoundedCornerShape(12.dp)).clickable{onSelect(p)},shape=RoundedCornerShape(12.dp),color=if(active)V2Brand else Color.Transparent){Row(Modifier.padding(12.dp,11.dp),verticalAlignment=Alignment.CenterVertically){Text(v2Glyph(p),color=if(active)Color.White else Color(0xFFAAB4C7),fontSize=18.sp,modifier=Modifier.width(30.dp));Text(p,color=if(active)Color.White else Color(0xFFE6EAF2),fontSize=13.sp,fontWeight=if(active)FontWeight.Bold else FontWeight.Medium)}}};Spacer(Modifier.weight(1f));Surface(Modifier.fillMaxWidth(),shape=RoundedCornerShape(14.dp),color=Color(0xFF222838)){Column(Modifier.padding(13.dp)){Text("STATUS TOKO",color=Color(0xFF929DB1),fontSize=10.sp,fontWeight=FontWeight.Bold);Text("●  Online     Supabase",color=Color.White,fontSize=11.sp,fontWeight=FontWeight.SemiBold,modifier=Modifier.padding(top=7.dp))}}}}}
private fun v2Glyph(p:String)=when(p){"Dashboard"->"⌂";"Penjualan"->"＋";"Produk"->"□";"Persediaan"->"▤";"Pembayaran"->"QR";"Laporan"->"▥";else->"⚙"}
@Composable private fun V2Bottom(selected:String,onSelect:(String)->Unit){val items=listOf("Dashboard","Penjualan","Produk","Persediaan");Surface(Modifier.fillMaxWidth().navigationBarsPadding(),color=Color.White,shadowElevation=12.dp){Row(Modifier.padding(6.dp),horizontalArrangement=Arrangement.spacedBy(4.dp)){items.forEach{p->val a=p==selected;Surface(Modifier.weight(1f).clip(RoundedCornerShape(12.dp)).clickable{onSelect(p)},shape=RoundedCornerShape(12.dp),color=if(a)V2Soft else Color.Transparent){Column(Modifier.padding(vertical=7.dp),horizontalAlignment=Alignment.CenterHorizontally){Text(v2Glyph(p),color=if(a)V2Brand else V2Muted,fontSize=17.sp);Text(p,color=if(a)V2Brand else V2Muted,fontSize=10.sp,fontWeight=if(a)FontWeight.Bold else FontWeight.Medium)}}}}}}

@Composable private fun V2Content(page:String,cart:List<V2Cart>,setCart:(List<V2Cart>)->Unit){when(page){"Dashboard"->V2Dashboard{pageNav->setCart(cart);/* navigation is handled by shell */};"Penjualan"->V2Sales(cart,setCart);"Produk"->V2Products();"Persediaan"->V2Inventory();"Pembayaran"->V2Payments();"Laporan"->V2Reports();else->V2Settings()}}
@Composable private fun V2Shell(title:String,subtitle:String,body:@Composable()->Unit){Column(Modifier.fillMaxSize().padding(20.dp,18.dp,20.dp,16.dp)){Text(title,color=V2Ink,fontSize=28.sp,fontWeight=FontWeight.ExtraBold);Text(subtitle,color=V2Muted,fontSize=12.sp,modifier=Modifier.padding(top=3.dp,bottom=16.dp));Box(Modifier.weight(1f).fillMaxWidth()){body()}}}

