@Composable private fun V2Metric(t:String,v:String,n:String,i:String,m:Modifier,w:Boolean=false){Card(m,shape=RoundedCornerShape(16.dp),colors=CardDefaults.cardColors(Color.White),elevation=CardDefaults.cardElevation(1.dp)){Row(Modifier.padding(13.dp),verticalAlignment=Alignment.CenterVertically){Box(Modifier.size(37.dp).clip(RoundedCornerShape(10.dp)).background(if(w)V2AmberSoft else V2Soft),contentAlignment=Alignment.Center){Text(i,color=if(w)V2Amber else V2Brand,fontWeight=FontWeight.Bold,fontSize=12.sp)};Column(Modifier.padding(start=9.dp)){Text(t,color=V2Muted,fontSize=9.sp);Text(v,color=V2Ink,fontSize=16.sp,fontWeight=FontWeight.ExtraBold);Text(n,color=if(w)V2Amber else V2Muted,fontSize=8.sp)}}}}
