@Composable private fun V2Sales(cart:List<V2Cart>,setCart:(List<V2Cart>)->Unit){var search by remember{mutableStateOf("")};var cat by remember{mutableStateOf("Semua")};var pay by remember{mutableStateOf(false)};val filtered=v2Products.filter{(cat=="Semua"||it.category==cat)&&(search.isBlank()||it.name.contains(search,true)||it.sku.contains(search,true))};val total=cart.sumOf{it.product.price*it.qty};V2Shell("Penjualan","Kasir • Toko Demo • ${v2Date()}"){Row(Modifier.fillMaxSize(),horizontalArrangement=Arrangement.spacedBy(14.dp)){Column(Modifier.weight(1.5f)){OutlinedTextField(search,{search=it},Modifier.fillMaxWidth(),singleLine=true,shape=RoundedCornerShape(13.dp),label={Text("Cari produk atau SKU")});Row(Modifier.horizontalScroll(rememberScrollState()).padding(vertical=9.dp),horizontalArrangement=Arrangement.spacedBy(7.dp)){listOf("Semua","Makanan","Minuman").forEach{Filter2(it,it==cat){cat=it}}};LazyVerticalGrid(columns=GridCells.Adaptive(145.dp),verticalArrangement=Arrangement.spacedBy(9.dp),horizontalArrangement=Arrangement.spacedBy(9.dp)){items(filtered){p->V2ProductTile(p){v2Add(p,cart,setCart)}}}};Card(Modifier.width(325.dp).fillMaxHeight(),shape=RoundedCornerShape(20.dp),colors=CardDefaults.cardColors(Color.White),elevation=CardDefaults.cardElevation(2.dp)){Column(Modifier.fillMaxSize().padding(16.dp)){Text("Keranjang",fontSize=18.sp,fontWeight=FontWeight.ExtraBold);Text("${cart.sumOf{it.qty}} item",color=V2Muted,fontSize=9.sp);Spacer(Modifier.height(8.dp));if(cart.isEmpty())Box(Modifier.weight(1f).fillMaxWidth(),contentAlignment=Alignment.Center){Text("Belum ada produk",color=V2Muted,fontSize=11.sp)}else LazyColumn(Modifier.weight(1f),verticalArrangement=Arrangement.spacedBy(8.dp)){items(cart){V2CartRow(it,cart,setCart)}};V2Line("Subtotal",v2Money(total));V2Line("Diskon","Rp 0");Row(Modifier.padding(top=7.dp)){Text("TOTAL",fontWeight=FontWeight.ExtraBold);Spacer(Modifier.weight(1f));Text(v2Money(total),color=V2Brand,fontSize=20.sp,fontWeight=FontWeight.ExtraBold)};Button({if(total>0)pay=true},modifier=Modifier.fillMaxWidth().padding(top=11.dp).height(50.dp),enabled=total>0,shape=RoundedCornerShape(13.dp)){Text("Lanjut Pembayaran",fontWeight=FontWeight.Bold)}}}};if(pay)V2Payment(total){pay=false;setCart(emptyList())}}
@Composable private fun Filter2(t:String,a:Boolean,on:()->Unit){Surface(Modifier.clip(RoundedCornerShape(10.dp)).clickable{on()},shape=RoundedCornerShape(10.dp),color=if(a)V2Brand else Color.White,shadowElevation=if(a)0.dp else 1.dp){Text(t,color=if(a)Color.White else V2Ink,fontSize=10.sp,fontWeight=if(a)FontWeight.Bold else FontWeight.Medium,modifier=Modifier.padding(12.dp,8.dp))}}
@Composable private fun V2ProductTile(p:V2Product,on:()->Unit){Card(Modifier.fillMaxWidth().height(145.dp).clickable{on()},shape=RoundedCornerShape(15.dp),colors=CardDefaults.cardColors(Color.White)){Column(Modifier.padding(12.dp)){Box(Modifier.fillMaxWidth().height(50.dp).clip(RoundedCornerShape(11.dp)).background(V2Soft),contentAlignment=Alignment.Center){Text(p.category.take(1),color=V2Brand,fontSize=20.sp,fontWeight=FontWeight.ExtraBold)};Text(p.name,color=V2Ink,fontSize=10.sp,fontWeight=FontWeight.Bold,maxLines=1,modifier=Modifier.padding(top=8.dp));Row(Modifier.padding(top=4.dp)){Text(v2Money(p.price),color=V2Brand,fontSize=10.sp,fontWeight=FontWeight.ExtraBold);Spacer(Modifier.weight(1f));Text("Stok ${p.stock}",color=if(p.stock<=7)V2Amber else V2Muted,fontSize=8.sp)}}}}
private fun v2Add(p:V2Product,c:List<V2Cart,set:(List<V2Cart>)->Unit){val old=c.firstOrNull{it.product.sku==p.sku};set(if(old==null)c+V2Cart(p,1)else c.map{if(it.product.sku==p.sku)it.copy(qty=it.qty+1)else it})}
@Composable private fun V2CartRow(line:V2Cart,c:List<V2Cart>,set:(List<V2Cart>)->Unit){Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(line.product.name,fontSize=9.sp,fontWeight=FontWeight.SemiBold);Text(v2Money(line.product.price),color=V2Muted,fontSize=8.sp)};Text("−",Modifier.clickable{v2Qty(line,-1,c,set)},color=V2Brand,fontSize=15.sp,fontWeight=FontWeight.Bold);Text(" ${line.qty} ",fontSize=10.sp,fontWeight=FontWeight.Bold);Text("+",Modifier.clickable{v2Qty(line,1,c,set)},color=V2Brand,fontSize=15.sp,fontWeight=FontWeight.Bold)}}
private fun v2Qty(line:V2Cart,d:Int,c:List<V2Cart>,set:(List<V2Cart>)->Unit){val n=line.qty+d;set(if(n<=0)c.filterNot{it.product.sku==line.product.sku}else c.map{if(it.product.sku==line.product.sku)it.copy(qty=n)else it})}
@Composable private fun V2Line(a:String,b:String){Row(Modifier.fillMaxWidth().padding(vertical=2.dp)){Text(a,color=V2Muted,fontSize=9.sp);Spacer(Modifier.weight(1f));Text(b,color=V2Ink,fontSize=9.sp,fontWeight=FontWeight.SemiBold)}}
